    @Override public void setupAnim(InfernalEntity e,float swing,float amount,float age,float yaw,float pitch){
        root.getAllParts().forEach(ModelPart::resetPose);
        ModelPart body=root.getChild("body");
        body.yRot=(float)Math.sin(age*.06)*.025F;
        body.y+=(float)Math.sin(swing*.7)*amount*.4F;
        for(ModelPart p:body.getAllParts().toList()){
            if(p==body)continue;
        }
        if(e.foundry()){
            if(e.attack()==1)body.getChild("hammer").xRot=-1.1F+(float)Math.sin(age*.15)*.1F;
            if(e.attack()==2||e.attack()==4)body.getChild("crucible").xRot=-1.15F;
            if(e.exposed())body.xRot=.12F;
        }else if(e.boss()){
            ModelPart head=body.getChild("head");
            for(int i=0;i<8;i++)head.getChild("jaw"+i).zRot+=e.attack()!=0?(float)Math.sin(age*.2)*.16F:0;
        }
        if(!e.boss()||e.foundry()){
            for(int i=0;i<2;i++)if(body.hasChild("leg"+i))body.getChild("leg"+i).xRot=(float)Math.cos(swing*.7+i*Math.PI)*amount*.5F;
        }else for(int i=0;i<6;i++)body.getChild("segment"+i).yRot=(float)Math.sin(age*.08-i*.6)*.09F;
    }
    @Override public void renderToBuffer(PoseStack pose,VertexConsumer v,int light,int overlay,float r,float g,float b,float a){root.render(pose,v,light,overlay,r,g,b,a);}
